-- Synthetic 1200-record fixture. Use after unchanged 01_schema.sql on an empty schema.

-- Word snapshot: 2026-11-14, Asia/Ho_Chi_Minh. Operational dates move together with CURRENT_DATE.

-- Historical snapshot import by schema owner; no historical routine replay is claimed.

SET search_path=lab_tracker,pg_catalog;

SET TIME ZONE 'Asia/Ho_Chi_Minh';

BEGIN;

CREATE FUNCTION pg_temp.fixture_date(d date) RETURNS date LANGUAGE sql STABLE AS $$ SELECT d + (CURRENT_DATE - DATE '2026-11-14') $$;

CREATE FUNCTION pg_temp.fixture_time(t timestamp) RETURNS timestamp LANGUAGE sql STABLE AS $$ SELECT t + (CURRENT_DATE - DATE '2026-11-14') * INTERVAL '1 day' $$;




















UPDATE chemical c SET quantity_in_stock=s.balance FROM (SELECT chemical_id,sum(CASE WHEN movement_type='Receipt' THEN quantity ELSE -quantity END) AS balance FROM chemical_movement GROUP BY chemical_id)s WHERE c.chemical_id=s.chemical_id;

SELECT setval(pg_get_serial_sequence('access_log','log_id'),(SELECT max(log_id) FROM access_log));

SELECT setval(pg_get_serial_sequence('borrow_transaction','borrow_id'),(SELECT max(borrow_id) FROM borrow_transaction));

SELECT setval(pg_get_serial_sequence('certification','cert_id'),(SELECT max(cert_id) FROM certification));

SELECT setval(pg_get_serial_sequence('chemical','chemical_id'),(SELECT max(chemical_id) FROM chemical));

SELECT setval(pg_get_serial_sequence('chemical_movement','movement_id'),(SELECT max(movement_id) FROM chemical_movement));

SELECT setval(pg_get_serial_sequence('equipment','equipment_id'),(SELECT max(equipment_id) FROM equipment));

SELECT setval(pg_get_serial_sequence('laboratory','lab_id'),(SELECT max(lab_id) FROM laboratory));

SELECT setval(pg_get_serial_sequence('maintenance_log','maintenance_id'),(SELECT max(maintenance_id) FROM maintenance_log));

SELECT setval(pg_get_serial_sequence('person','person_id'),(SELECT max(person_id) FROM person));

SELECT setval(pg_get_serial_sequence('research_grant','grant_id'),(SELECT max(grant_id) FROM research_grant));

